            C#

    using System;

class GFG {
    static void Main() {
        Console.Write("Enter your age, height, grade, and name: ");
        string[] inputs = Console.ReadLine().Split();

        int age = int.Parse(inputs[0]);
        float height = float.Parse(inputs[1]);
        char grade = char.Parse(inputs[2]);
        string name = inputs[3];

        Console.WriteLine("Your age: " + age);
        Console.WriteLine("Your height: " + height);
        Console.WriteLine("Your grade: " + grade);
        Console.WriteLine("Your name: " + name);
    }
}

Input: 20 5.9 A AliceOutput:Your age: 20Your height: 5.9Your grade: AYour name: AliceInput Output in JavaScriptIn Node.js, input/output is handled using readline module for input and console.log() for output.console.log() displays messages or values on the screen and moves to a new line.console.print() is not standard; output is mostly done via console.log().Input is read using readline.question() in Node.js or prompt() in browsers.
            JavaScript

    const readline = require('readline').createInterface({
  input: process.stdin,
  output: process.stdout
});

readline.question('Enter your age, height, grade, and name (space separated): ', input => {
    const [age, height, grade, name] = input.split(' ');
    console.log(`Your age: ${age}`);
    console.log(`Your height: ${height}`);
    console.log(`Your grade: ${grade}`);
    console.log(`Your name: ${name}`);
    readline.close();
});

